// ---------- 1. SETTINGS: change numbers here, nowhere else ----------
const STAGES = [
  { name: 'headsup',  day: -3 },   // negative = 3 days BEFORE the due date
  { name: 'friendly', day: 3 },
  { name: 'firm',     day: 10 },
  { name: 'final',    day: 21 },
];
const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

// ---------- 2. HELPERS: each turns messy input into clean data, or throws ----------
function toDayNumber(value) {
  if (value === undefined || value === null || String(value).trim() === '') {
    throw new Error('date is empty');
  }
  const text = String(value).trim();

  // Google Sheets sometimes sends a date as a serial number like 46335
  if (typeof value === 'number' || /^\d{5}$/.test(text)) {
    return Math.floor(Number(value)) - 25569;   // 25569 = Sheets' day 0 -> 1 Jan 1970
  }
  // "2026-11-13"
  let m = text.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return Date.UTC(+m[1], +m[2] - 1, +m[3]) / 86400000;

  // "4 Nov 2026"
  m = text.match(/^(\d{1,2})\s+([A-Za-z]+)\s+(\d{4})$/);
  if (m) {
    const month = MONTHS.findIndex(x => x.toLowerCase() === m[2].slice(0, 3).toLowerCase());
    if (month >= 0) return Date.UTC(+m[3], month, +m[1]) / 86400000;
  }
  throw new Error(`unreadable date "${text}"`);   // refuse to guess (4 Nov or 11 Apr?)
}

function dayNumberToText(n) {
  const d = new Date(n * 86400000);
  return `${d.getUTCDate()} ${MONTHS[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
}

function toAmount(value) {
  if (typeof value === 'number') return value;
  const cleaned = String(value ?? '').replace(/[^0-9.\-]/g, '');   // keep only digits . -
  const n = parseFloat(cleaned);
  if (cleaned === '' || Number.isNaN(n)) throw new Error(`unreadable amount "${value}"`);
  return n;
}

function stageIndex(text) {
  const key = String(text ?? '').toLowerCase().replace(/[^a-z]/g, '');   // "Heads-up " -> "headsup"
  if (key === '') return -1;                        // nothing sent yet
  const i = STAGES.findIndex(s => s.name === key);
  if (i === -1) throw new Error(`unknown stage "${text}"`);
  return i;
}

const looksLikeEmail = e => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(e ?? '').trim());

// ---------- 3. THE DECISION FOR ONE ROW ----------
const today = toDayNumber($now.setZone('Asia/Karachi').toFormat('yyyy-MM-dd'));
const seen = new Set();   // invoice numbers already met in this run

function processRow(row, base) {
  if (base.invoiceNo === '') throw new Error('missing invoice number');

  // duplicates: first one wins, later ones are reported, not silently dropped
  const key = base.invoiceNo.toUpperCase();
  if (seen.has(key)) {
    return { ...base, action: 'skip_duplicate', reason: 'same invoice number appeared earlier', needsAttention: false };
  }
  seen.add(key);

  // status first: a Paid row with a garbled amount is none of our business
  const status = String(row['Status'] ?? '').trim().toLowerCase();
  if (status === 'paid')     return { ...base, action: 'skip_paid', reason: 'already paid', needsAttention: false };
  if (status === 'disputed') return { ...base, action: 'skip_disputed', reason: 'disputed, Imran handles it', needsAttention: true };
  if (status !== 'unpaid')   throw new Error(`unknown status "${row['Status']}"`);

  // fields every decision needs
  const due = toDayNumber(row['Due Date']);
  const daysOverdue = today - due;                  // negative = not due yet
  const lastIdx = stageIndex(row['Last Reminder Stage']);

  // which stage SHOULD this invoice be at? the highest threshold already reached
  let targetIdx = -1;
  for (let i = 0; i < STAGES.length; i++) {
    if (daysOverdue >= STAGES[i].day) targetIdx = i;
  }

  const details = {
    ...base,
    clientEmail: String(row['Client Email'] ?? '').trim(),
    amount: toAmount(row['Amount']),
    currency: row['Currency'],
    dueDate: dayNumberToText(due),
    daysOverdue,
    lastStage: lastIdx === -1 ? '' : STAGES[lastIdx].name,
    targetStage: targetIdx === -1 ? '' : STAGES[targetIdx].name,
  };

  if (targetIdx === -1) {
    return { ...details, action: 'not_due', reason: `due in ${-daysOverdue} days`, needsAttention: false };
  }
  const isFinal = targetIdx === STAGES.length - 1;
  if (targetIdx <= lastIdx) {
    return { ...details, action: 'already_sent', reason: `${details.targetStage} already sent`, needsAttention: isFinal };
  }
  // only now does the email matter, because only now would we send
  if (!looksLikeEmail(row['Client Email'])) {
    return { ...details, action: 'error', reason: `bad or missing email "${row['Client Email'] ?? ''}"`, needsAttention: true };
  }
  return { ...details, action: 'send_' + details.targetStage, reason: `${daysOverdue} days from due date`, needsAttention: isFinal };
}

// ---------- 4. LOOP: one bad row must never stop the others ----------
const results = [];
for (const item of $input.all()) {
  const row = item.json;
  const base = {
    rowNumber: row.row_number ?? null,
    invoiceNo: String(row['Invoice No'] ?? '').trim(),
    clientName: row['Client Name'] ?? '',
  };
  try {
    results.push(processRow(row, base));
  } catch (err) {
    results.push({ ...base, action: 'error', reason: err.message, needsAttention: true });
  }
}
return results.map(r => ({ json: r }));

// every row the decision node produced (the plan)
const rows = $('Decide action per invoice').all().map(i => i.json);
const sheetRows = $('read invoice sheet').all().length;   // your read node's name
const sourceCheck = sheetRows === rows.length
  ? `Source check OK: ${sheetRows} rows in sheet, ${rows.length} decided`
  : `⚠️ SOURCE CHECK FAILED: ${sheetRows} rows in sheet but ${rows.length} decided`;
const count = action => rows.filter(r => r.action === action).length;
const planned = rows.filter(r => r.action.startsWith('send_'));

// what actually happened (read from nodes that run AFTER the plan)
const fromNode = (name, branch) => { try { return $(name).all(branch); } catch (e) { return []; } };
const sentCount   = fromNode('Send reminder email', 0).length;     // Gmail success output
const failedCount = fromNode('Send reminder email', 1).length;     // Gmail error output
const recorded    = fromNode('Record reminder in sheet', 0).map(i => i.json['Invoice No']);
const unconfirmed = planned.filter(r => !recorded.includes(r.invoiceNo));
const deliveryOk  = sentCount === planned.length && failedCount === 0 && unconfirmed.length === 0;
const deliveryLine = deliveryOk
  ? `Sent: ${sentCount} of ${planned.length} planned`
  : `⚠️ PLANNED ${planned.length}, SENT ${sentCount}, FAILED ${failedCount}. Not confirmed: ${unconfirmed.map(r => r.invoiceNo).join(', ') || 'none'}`;

// overdue = more than 0 days past due, with a readable amount
const overdue = rows.filter(r => r.amount !== undefined && r.daysOverdue > 0);
const totals = {};
for (const r of overdue) totals[r.currency] = (totals[r.currency] || 0) + r.amount;
const totalText = Object.entries(totals)
  .map(([cur, amt]) => `${amt.toLocaleString('en-US', { minimumFractionDigits: 2 })} ${cur}`)
  .join(' | ') || 'none';

// Discord rejects messages over 2000 characters, so cap the list
const attention = rows.filter(r => r.needsAttention);
const shown = attention.slice(0, 15).map(r => `• ${r.invoiceNo} (${r.clientName}): ${r.action}, ${r.reason}`);
if (attention.length > 15) shown.push(`...and ${attention.length - 15} more`);

// reconciliation: every row must land in exactly one bucket
const actions = ['send_headsup','send_friendly','send_firm','send_final','skip_paid','skip_disputed',
                 'skip_duplicate','already_sent','not_due','error'];
const counted = actions.reduce((sum, a) => sum + count(a), 0);
const check = counted === rows.length
  ? `Check OK: ${rows.length} rows read, ${counted} accounted for`
  : `⚠️ CHECK FAILED: ${rows.length} rows read but only ${counted} accounted for`;

const message = [
  deliveryLine,
  `Heads-up ${count('send_headsup')} | Friendly ${count('send_friendly')} | Firm ${count('send_firm')} | Final ${count('send_final')}`,
  `Overdue total: ${totalText}`,
  `Errors: ${count('error')} | Skipped: ${count('skip_paid')} paid, ${count('skip_disputed')} disputed, ${count('skip_duplicate')} duplicate, ${count('already_sent')} already sent, ${count('not_due')} not due`,
  attention.length ? `Needs your attention (${attention.length}):\n${shown.join('\n')}` : 'Nothing needs your attention.',
  check,
  sourceCheck,
].join('\n');

return [{ json: { message } }];

const money = r => `${r.amount.toLocaleString('en-US', { minimumFractionDigits: 2 })} ${r.currency}`;
const details = r => `Invoice: ${r.invoiceNo}\nAmount: ${money(r)}\nDue date: ${r.dueDate}`;
const SIGN_OFF = 'Regards,\nImran | Tidewater Design Studio';

const TEMPLATES = {
  headsup: {
    subject: r => `Invoice ${r.invoiceNo} is due on ${r.dueDate}`,
    body: r => `Hi ${r.clientName},\n\nA quick heads-up that the invoice below falls due on ${r.dueDate}.\n\n${details(r)}\n\nIf payment is already arranged, please ignore this note.`,
  },
  friendly: {
    subject: r => `Friendly reminder: invoice ${r.invoiceNo}`,
    body: r => `Hi ${r.clientName},\n\nI hope you're well. Our records show the invoice below is now ${r.daysOverdue} days overdue. It may simply have slipped through, so a quick check on your side would be appreciated.\n\n${details(r)}\n\nIf payment is already on its way, thank you, and please disregard this note. If you have any question about the invoice, just reply and I'll sort it out.`,
  },
  firm: {
    subject: r => `Invoice ${r.invoiceNo} is ${r.daysOverdue} days overdue`,
    body: r => `Hi ${r.clientName},\n\nThe invoice below is now ${r.daysOverdue} days overdue and I haven't yet received payment.\n\n${details(r)}\n\nCould you please arrange payment in the next few days, or reply with the date it will be paid? If something is holding it up, let me know and I'll help resolve it.`,
  },
  final: {
    subject: r => `Final reminder: invoice ${r.invoiceNo} (${r.daysOverdue} days overdue)`,
    body: r => `Hi ${r.clientName},\n\nDespite my earlier reminders, the invoice below remains unpaid and is now ${r.daysOverdue} days overdue.\n\n${details(r)}\n\nI'd be grateful if you could settle it within the next 2 working days, or write back today with a confirmed payment date. If there is a problem with the invoice, please tell me right away so we can resolve it.\n\nThank you for your prompt attention.`,
  },
};

return $input.all().map((item, index) => {
  const r = item.json;
  const t = TEMPLATES[r.targetStage];
  if (!t) throw new Error(`no email template for stage "${r.targetStage}" (invoice ${r.invoiceNo})`);
  return {
    json: { ...r, subject: t.subject(r), body: t.body(r) + '\n\n' + SIGN_OFF },
    pairedItem: { item: index },
  };
});
